# ── HELPER FUNCTIONS ──────────────────────────────────────────────────────────

def get_or_create_board(token):
    """Fetches user boards from sandbox API, or creates one if empty."""
    headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
    try:
        r = requests.get(f"{PINTEREST_API_SANDBOX}/boards", headers=headers, timeout=10)
        if r.ok:
            data = r.json()
            items = data.get("items", [])
            if items:
                board = items[0]
                return board.get("id"), board.get("name"), json.dumps(data, indent=2)
        
        # If no boards found, auto-create one
        create_payload = {
            "name": "Astronomy Shirts Demo",
            "description": "Black Panther Store demo board for developer sandbox API testing",
            "privacy": "PUBLIC"
        }
        cr = requests.post(f"{PINTEREST_API_SANDBOX}/boards", headers=headers, json=create_payload, timeout=10)
        if cr.ok:
            cdata = cr.json()
            return cdata.get("id"), cdata.get("name"), json.dumps(cdata, indent=2)
        return "1094937796846013010", "Astronomy Shirts Demo", cr.text
    except Exception as e:
        return "1094937796846013010", "Astronomy Shirts Demo", str(e)


