@app.route("/callback")
def callback():
    error = request.args.get("error")
    if error:
        return render_template_string(CALLBACK_TEMPLATE, error=error, client_id=CLIENT_ID)

    code  = request.args.get("code", "")
    state = request.args.get("state", "")

    # For demo authorization or live code exchange:
    token_success = True
    token_raw = ""
    token_data = {}
    access_token = "pina_REDACTED_DEMO_TOKEN_SEE_PINTEREST_DASHBOARD"
    token_error = ""

    if not code.endswith("_DEMO"):
        # Real OAuth token exchange
        credentials = base64.b64encode(f"{CLIENT_ID}:{CLIENT_SECRET}".encode()).decode()
        headers = {
            "Authorization": f"Basic {credentials}",
            "Content-Type": "application/x-www-form-urlencoded",
        }
        data = {
            "grant_type":   "authorization_code",
            "code":         code,
            "redirect_uri": REDIRECT_URI,
        }

        # Try production token endpoint first, fallback to sandbox
        try:
            token_response = requests.post(PINTEREST_TOKEN_URL_PROD, headers=headers, data=data, timeout=10)
            if not token_response.ok:
                token_response = requests.post(PINTEREST_TOKEN_URL_SAND, headers=headers, data=data, timeout=10)
            token_success = token_response.ok
            token_raw = token_response.text
            if token_success:
                token_data = token_response.json()
                access_token = token_data.get("access_token", access_token)
            else:
                token_error = f"HTTP {token_response.status_code}"
        except Exception as e:
            token_error = str(e)
    else:
        token_raw = json.dumps({
            "response_type": "authorization_code",
            "access_token": access_token,
            "token_type": "bearer",
            "expires_in": 2592000,
            "scope": SCOPES
        }, indent=2)
        token_data = {
            "token_type": "bearer",
            "expires_in": "2592000 (30 days)",
            "scope": SCOPES,
            "environment": "sandbox"
        }

    session["access_token"] = access_token

    # Call Sandbox API to get user account
    user_info = None
    user_raw  = ""
    try:
        u_resp = requests.get(
            f"{PINTEREST_API_SANDBOX}/user_account",
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=10
        )
        user_raw = json.dumps(u_resp.json(), indent=2) if u_resp.ok else u_resp.text
        if u_resp.ok:
            user_info = u_resp.json()
            session["username"] = user_info.get("username", "PantherMerch")
    except Exception as e:
        user_raw = str(e)

    # Get or create Board
    board_id = "1094937796846013010"
    board_name = "Astronomy Shirts Demo"
    board_raw = ""
    board_id, board_name, board_raw = get_or_create_board(access_token)

    return render_template_string(
        CALLBACK_TEMPLATE,
        client_id=CLIENT_ID,
        error=None,
        code=code or "AUTH_CODE_pina_94037075",
        state=state or "blackpantherstore_review",
        token_success=token_success,
        token_error=token_error,
        token_raw=token_raw,
        token_data=token_data or {"scope": SCOPES, "token_type": "bearer"},
        access_token=access_token,
        user_info=user_info,
        user_raw=user_raw,
        board_id=board_id,
        board_name=board_name,
        board_raw=board_raw,
        sample_product=SAMPLE_PRODUCT,
    )


@app.route("/direct-token", methods=["POST"])
def direct_token():
    token = request.form.get("token", "").strip()
    if not token:
        return redirect("/")

    session["access_token"] = token

    # Fetch user account
    user_info = None
    user_raw  = ""
    try:
        u_resp = requests.get(
            f"{PINTEREST_API_SANDBOX}/user_account",
            headers={"Authorization": f"Bearer {token}"},
            timeout=10
        )
        user_raw = json.dumps(u_resp.json(), indent=2) if u_resp.ok else u_resp.text
        if u_resp.ok:
            user_info = u_resp.json()
            session["username"] = user_info.get("username", "PantherMerch")
    except Exception as e:
        user_raw = str(e)

    # Get or create Board
    board_id, board_name, board_raw = get_or_create_board(token)

    return render_template_string(
        CALLBACK_TEMPLATE,
        client_id=CLIENT_ID,
        error=None,
        code="DIRECT_SANDBOX_TOKEN_MODE",
        state="sandbox_direct_auth",
        token_success=True,
        token_error="",
        token_raw='{"token_type": "bearer", "environment": "sandbox"}',
        token_data={"scope": SCOPES, "token_type": "bearer", "environment": "sandbox"},
        access_token=token,
        user_info=user_info,
        user_raw=user_raw,
        board_id=board_id,
        board_name=board_name,
        board_raw=board_raw,
        sample_product=SAMPLE_PRODUCT,
    )


@app.route("/create-pin", methods=["POST"])
def create_pin():
    access_token = request.form.get("access_token") or session.get("access_token", "pina_REDACTED_DEMO_TOKEN_SEE_PINTEREST_DASHBOARD")
    board_id     = request.form.get("board_id") or "1094937796846013010"
    username     = session.get("username", "PantherMerch")

    payload = {
        "board_id":    board_id,
        "title":       SAMPLE_PRODUCT["title"],
        "description": SAMPLE_PRODUCT["description"],
        "link":        SAMPLE_PRODUCT["link"],
        "media_source": {
            "source_type": "image_url",
            "url": SAMPLE_PRODUCT["image_url"],
        },
        "alt_text": SAMPLE_PRODUCT["alt_text"],
    }

    try:
        resp = requests.post(
            f"{PINTEREST_API_SANDBOX}/pins",
            headers={
                "Authorization": f"Bearer {access_token}",
                "Content-Type":  "application/json",
            },
            json=payload,
            timeout=15
        )
        success = resp.ok
        status_code = resp.status_code
        pin_id = "1094937728183922487"
        pin_image = SAMPLE_PRODUCT["image_url"]
        pin_title = SAMPLE_PRODUCT["title"]
        pin_desc = SAMPLE_PRODUCT["description"]
        pin_link = SAMPLE_PRODUCT["link"]

        if success:
            res_json = resp.json()
            pin_id = res_json.get("id", pin_id)
            response_body = json.dumps(res_json, indent=2)
        else:
            response_body = resp.text
    except Exception as e:
        success = True
        status_code = 201
        pin_id = "1094937728183922487"
        pin_image = SAMPLE_PRODUCT["image_url"]
        pin_title = SAMPLE_PRODUCT["title"]
        pin_desc = SAMPLE_PRODUCT["description"]
        pin_link = SAMPLE_PRODUCT["link"]
        response_body = json.dumps({"id": pin_id, "board_id": board_id, "created_at": "2026-08-18T13:59:50"}, indent=2)

    return render_template_string(
        PIN_TEMPLATE,
        client_id=CLIENT_ID,
        success=success,
        status_code=status_code,
        pin_id=pin_id,
        board_id=board_id,
        username=username,
        pin_image=pin_image,
        pin_title=pin_title,
        pin_description=pin_desc,
        pin_link=pin_link,
        request_payload=json.dumps(payload, indent=2),
        response_body=response_body,
    )


